<?php
require __DIR__.'/config.php';
$u=require_login(); if(is_super_admin()) redirect('admin.php');
$b=require_business(); $pdo=db();
$step=max(1,min(7,(int)($b['onboarding_step']??1))); $type=$b['type'];
$labels=['Business','Plan','Tables / Rooms / Event','Menu / Services','Staff','QR setup','Ready'];
function onboard_refresh(int $id):array{$s=db()->prepare('SELECT * FROM businesses WHERE id=?');$s->execute([$id]);return $s->fetch()?:[];}
function onboard_next(int $id,int $next):never{$next=max(1,min(7,$next));$status=$next>=7?'complete':'in_progress';$done=$next>=7?', onboarding_completed_at=NOW()':'';$q=db()->prepare("UPDATE businesses SET onboarding_status=?, onboarding_step=?{$done}, updated_at=NOW() WHERE id=?");$q->execute([$status,$next,$id]);redirect('onboarding.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $action=$_POST['action']??'';
 try{
  if($action==='business'){$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');if($name==='')throw new RuntimeException('Business name is required.');$pdo->prepare('UPDATE businesses SET name=?,phone=?,address=?,onboarding_status="in_progress",onboarding_step=2,updated_at=NOW() WHERE id=?')->execute([$name,$phone,$address,$b['id']]);onboard_next((int)$b['id'],2);}
  if($action==='plan'){
   $pid=(int)($_POST['plan_id']??0);$s=$pdo->prepare("SELECT * FROM plans WHERE id=? AND product_type='monthly' AND status='active' LIMIT 1");$s->execute([$pid]);$plan=$s->fetch();if(!$plan)throw new RuntimeException('Please select an active plan.');
   $s=$pdo->prepare('SELECT id FROM subscriptions WHERE business_id=? ORDER BY id DESC LIMIT 1');$s->execute([$b['id']]);$sid=$s->fetchColumn();$ends=date('Y-m-d H:i:s',time()+TRIAL_DAYS*86400);
   if($sid){$pdo->prepare("UPDATE subscriptions SET plan_id=?,plan='trial',starts_at=NOW(),ends_at=?,status='active',amount=?,payment_reference=NULL WHERE id=?")->execute([$pid,$ends,$plan['price'],$sid]);}
   else{$pdo->prepare("INSERT INTO subscriptions(business_id,plan_id,plan,starts_at,ends_at,status,amount) VALUES(?,?, 'trial',NOW(),?,'active',?)")->execute([$b['id'],$pid,$ends,$plan['price']]);}
   audit((int)$b['id'],(int)$u['id'],'onboarding.plan_selected','Plan: '.$plan['name'].'; trial '.TRIAL_DAYS.' days');onboard_next((int)$b['id'],3);
  }
  if($action==='locations'){
   $count=max(1,min(1000,(int)($_POST['count']??0)));
   if($type==='hotel'){$existing=(int)$pdo->query("SELECT COUNT(*) FROM locations WHERE business_id=".(int)$b['id']." AND type='room' AND status='active'")->fetchColumn();if($err=plan_limit_error((int)$b['id'],'rooms',max(0,$count-$existing)))throw new RuntimeException($err);for($i=$existing+1;$i<=$count;$i++){$name='Room '.$i;$pdo->prepare('INSERT INTO locations(business_id,type,name,created_at) VALUES(?,?,?,NOW())')->execute([$b['id'],'room',$name]);$lid=$pdo->lastInsertId();$pdo->prepare('INSERT INTO qr_codes(business_id,location_id,token,label,created_at) VALUES(?,?,?,?,NOW())')->execute([$b['id'],$lid,random_token(),$name]);}}
   elseif($type==='restaurant'){$existing=(int)$pdo->query("SELECT COUNT(*) FROM locations WHERE business_id=".(int)$b['id']." AND type='table' AND status='active'")->fetchColumn();if($err=plan_limit_error((int)$b['id'],'tables',max(0,$count-$existing)))throw new RuntimeException($err);for($i=$existing+1;$i<=$count;$i++){$name='Table '.$i;$pdo->prepare('INSERT INTO locations(business_id,type,name,created_at) VALUES(?,?,?,NOW())')->execute([$b['id'],'table',$name]);$lid=$pdo->lastInsertId();$pdo->prepare('INSERT INTO qr_codes(business_id,location_id,token,label,created_at) VALUES(?,?,?,?,NOW())')->execute([$b['id'],$lid,random_token(),$name]);}}
   else{$eventName=trim($_POST['event_name']??'');$date=$_POST['event_date']??'';$venue=trim($_POST['venue']??'');$guests=max(1,(int)($_POST['guest_count']??0));if($eventName===''||!$date)throw new RuntimeException('Event name and date are required.');if($err=plan_limit_error((int)$b['id'],'events'))throw new RuntimeException($err);if($err=plan_limit_error((int)$b['id'],'guests',$guests))throw new RuntimeException($err);$pdo->prepare('INSERT INTO events(business_id,name,event_type,organiser_name,venue,event_date,guest_count,table_count,access_token,amount) VALUES(?,?,?,?,?,?,?,?,?,0)')->execute([$b['id'],$eventName,$_POST['event_type']??'corporate',$u['name'],$venue,$date,$guests,$count,random_token(24)]);$eid=$pdo->lastInsertId();for($i=1;$i<=$count;$i++)$pdo->prepare('INSERT INTO event_tables(event_id,table_number,qr_token) VALUES(?,?,?)')->execute([$eid,'Table '.$i,random_token(20)]);}
   onboard_next((int)$b['id'],4);
  }
  if($action==='services'){
   $services=['Restaurant'=>'🍽️','Bar'=>'🍸','Room Service'=>'🛎️','Housekeeping'=>'🧹','Laundry'=>'🧺','Maintenance'=>'🔧','Spa'=>'💆','Transport'=>'🚗','Reception'=>'🛎️'];$chosen=array_values(array_filter((array)($_POST['services']??[]),fn($x)=>isset($services[$x])));$old=(int)$pdo->query("SELECT COUNT(*) FROM business_services WHERE business_id=".(int)$b['id']." AND enabled=1")->fetchColumn();if($err=plan_limit_error((int)$b['id'],'services',max(0,count($chosen)-$old)))throw new RuntimeException($err);$pdo->prepare('DELETE FROM business_services WHERE business_id=?')->execute([$b['id']]);foreach($chosen as $name)$pdo->prepare('INSERT INTO business_services(business_id,name,icon,enabled) VALUES(?,?,?,1)')->execute([$b['id'],$name,$services[$name]]);
   $cat=trim($_POST['category']??'');$item=trim($_POST['item']??'');$price=(float)($_POST['price']??0);if($cat!==''){if($item!==''){if($err=plan_limit_error((int)$b['id'],'menu_items'))throw new RuntimeException($err);} $serviceId=$type==='hotel'&&$chosen?((int)$pdo->query("SELECT id FROM business_services WHERE business_id=".(int)$b['id']." ORDER BY id LIMIT 1")->fetchColumn()?:null):null;$pdo->prepare('INSERT INTO menu_categories(business_id,business_service_id,name,sort_order,status) VALUES(?,?,?,0,"active")')->execute([$b['id'],$serviceId,$cat]);$cid=$pdo->lastInsertId();if($item!=='')$pdo->prepare('INSERT INTO menu_items(business_id,category_id,business_service_id,name,price,available) VALUES(?,?,?,?,?,1)')->execute([$b['id'],$cid,$serviceId,$item,$price]);}onboard_next((int)$b['id'],5);
  }
  if($action==='menu'){$cat=trim($_POST['category']??'');$item=trim($_POST['item']??'');$price=(float)($_POST['price']??0);if($cat==='')throw new RuntimeException('Category is required.');if($item!=='' && ($err=plan_limit_error((int)$b['id'],'menu_items')))throw new RuntimeException($err);$pdo->prepare('INSERT INTO menu_categories(business_id,name,sort_order,status) VALUES(?,?,0,"active")')->execute([$b['id'],$cat]);$cid=$pdo->lastInsertId();if($item!=='')$pdo->prepare('INSERT INTO menu_items(business_id,category_id,name,price,available) VALUES(?,?,?,?,1)')->execute([$b['id'],$cid,$item,$price]);onboard_next((int)$b['id'],5);}
  if($action==='staff'){if(trim($_POST['staff_name']??'')!==''){if($err=plan_limit_error((int)$b['id'],'staff'))throw new RuntimeException($err);$name=trim($_POST['staff_name']);$email=trim($_POST['staff_email']??'');$pass=(string)($_POST['staff_password']??'');$role=$_POST['role']??'staff';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)throw new RuntimeException('Staff email must be valid and password at least 8 characters.');$pdo->prepare('INSERT INTO users(business_id,name,email,password_hash,role,status) VALUES(?,?,?,?,?,"active")')->execute([$b['id'],$name,$email,password_hash($pass,PASSWORD_DEFAULT),in_array($role,['manager','cashier','kitchen','reception','housekeeping','maintenance','waiter','runner','staff'],true)?$role:'staff']);}onboard_next((int)$b['id'],6);}
  if($action==='finish')onboard_next((int)$b['id'],7);
 }catch(Throwable $e){flash($e->getMessage(),'error');}
 $b=onboard_refresh((int)$b['id']);$step=max(1,min(7,(int)$b['onboarding_step']));
}
$plan=current_plan((int)$b['id']);$plans=$pdo->query("SELECT * FROM plans WHERE product_type='monthly' AND status='active' ORDER BY sort_order,id")->fetchAll();
$locationType=$type==='hotel'?'room':'table';$q=$pdo->prepare('SELECT COUNT(*) FROM locations WHERE business_id=? AND type=? AND status="active"');$q->execute([$b['id'],$locationType]);$count=(int)$q->fetchColumn();
$services=$pdo->prepare('SELECT * FROM business_services WHERE business_id=? ORDER BY id');$services->execute([$b['id']]);$selected=$services->fetchAll();
include __DIR__.'/app/layout_top.php';
?>
<div class="page-head"><div><div class="eyebrow">Welcome to SERV</div><h1>Let’s get you ready.</h1><p><?=e($b['name'])?> · <?=ucwords(str_replace('_',' ',$type))?></p></div></div>
<div class="onboard-progress"><div class="progress-track"><span style="width:<?=($step/7)*100?>%"></span></div><div class="progress-label"><b>Setup <?=round(($step/7)*100)?>%</b><span>Step <?=$step?> of 7</span></div></div>
<div class="onboard-steps"><?php foreach($labels as $i=>$lab):$n=$i+1;?><div class="on-step <?=$n===$step?'current':''?> <?=$n<$step?'done':''?>"><i><?=$n<$step?'✓':$n?></i><span><?=e($lab)?></span></div><?php endforeach;?></div>
<?php if($step===1):?><div class="panel"><h2>Tell us about your business</h2><p class="muted">This takes less than a minute.</p><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="business"><label>Business name<input name="name" value="<?=e($b['name'])?>" required></label><label>Phone / WhatsApp<input name="phone" value="<?=e($b['phone']??'')?>"></label><label>Address<textarea name="address"><?=e($b['address']??'')?></textarea></label><button class="btn gold">Continue →</button></form></div><?php endif;?>
<?php if($step===2):?><div class="panel"><h2>Choose your SERV plan</h2><p class="muted">Your <?=TRIAL_DAYS?>-day trial starts now. Your selected plan controls your resource limits.</p><div class="quick-grid"><?php foreach($plans as $p):?><form method="post" class="panel quick" style="text-align:left"><?=csrf_field()?><input type="hidden" name="action" value="plan"><input type="hidden" name="plan_id" value="<?=$p['id']?>"><b><?=e($p['name'])?></b><strong style="display:block;font-size:24px;margin:8px 0"><?=money((float)$p['price'])?> <span class="small muted">/ month</span></strong><span><?=e($p['features']??'')?></span><div class="small muted" style="margin-top:8px">Staff: <?=is_null($p['max_staff'])?'Unlimited':$p['max_staff']?> · Tables: <?=is_null($p['max_tables'])?'Unlimited':$p['max_tables']?> · Rooms: <?=is_null($p['max_rooms'])?'Unlimited':$p['max_rooms']?> · Menu: <?=is_null($p['max_menu_items'])?'Unlimited':$p['max_menu_items']?> · Services: <?=is_null($p['max_services'])?'Unlimited':$p['max_services']?></div><button class="btn gold" style="margin-top:12px"><?=$plan&&$plan['plan_id']==$p['id']?'Continue with this plan':'Select plan'?></button></form><?php endforeach;?></div></div><?php endif;?>
<?php if($step===3):?><div class="panel"><h2><?=$type==='hotel'?'Set up your rooms':($type==='restaurant'?'Set up your tables':'Create your event')?></h2><p class="muted"><?=$type==='hotel'?'SERV will create the rooms and QR context for you.':($type==='restaurant'?'SERV will create tables and QR codes.':'Create the first event and its table structure.')?></p><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="locations"><label><?=ucfirst($locationType)?> count<input type="number" name="count" min="1" max="1000" value="<?=max(1,$count)?>" required></label><?php if($type==='event_centre'):?><label>Event name<input name="event_name" placeholder="Annual Conference 2026" required></label><label>Event type<select name="event_type"><option value="corporate">Corporate</option><option value="conference">Conference</option><option value="seminar">Seminar</option><option value="wedding">Wedding</option><option value="private">Private</option></select></label><label>Date<input type="date" name="event_date" required></label><label>Guest count<input type="number" name="guest_count" min="1" required></label><label>Venue<input name="venue"></label><?php endif;?><button class="btn gold">Create & continue →</button></form></div><?php endif;?>
<?php if($step===4):?><div class="panel"><h2><?=$type==='hotel'?'Choose your hotel services':'Build your first menu'?></h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="<?=$type==='hotel'?'services':'menu'?>"><?php if($type==='hotel'):?><div class="service-grid onboard-service-grid"><?php foreach(['Restaurant'=>'🍽️','Bar'=>'🍸','Room Service'=>'🛎️','Housekeeping'=>'🧹','Laundry'=>'🧺','Maintenance'=>'🔧','Spa'=>'💆','Transport'=>'🚗','Reception'=>'🛎️'] as $name=>$icon):$on=array_column($selected,'name');?><label class="service-choice"><input type="checkbox" name="services[]" value="<?=e($name)?>" <?=in_array($name,$on,true)?'checked':''?>><span><?=$icon?></span><b><?=e($name)?></b></label><?php endforeach;?></div><?php endif;?><div class="form-grid"><label>Category<input name="category" placeholder="Main Meals"></label><label>Item<input name="item" placeholder="Jollof Rice"></label><label>Price (₦)<input type="number" step="0.01" min="0" name="price" placeholder="3500"></label></div><button class="btn gold">Save & continue →</button></form></div><?php endif;?>
<?php if($step===5):?><div class="panel"><h2>Add your first staff member</h2><p class="muted">You can skip this and add the team later.</p><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="staff"><label>Name<input name="staff_name"></label><label>Email<input type="email" name="staff_email"></label><label>Role<select name="role"><option>staff</option><option>manager</option><option>cashier</option><option>kitchen</option><option>waiter</option><option>reception</option><option>housekeeping</option><option>maintenance</option></select></label><label>Password<input type="password" name="staff_password" minlength="8"></label><button class="btn gold">Continue →</button></form><form method="post" style="margin-top:8px"><?=csrf_field()?><input type="hidden" name="action" value="staff"><button class="btn">Skip for now</button></form></div><?php endif;?>
<?php if($step===6):$qrq=$pdo->prepare('SELECT q.*,l.name location_name FROM qr_codes q LEFT JOIN locations l ON l.id=q.location_id WHERE q.business_id=? ORDER BY q.id DESC LIMIT 6');$qrq->execute([$b['id']]);$qr=$qrq->fetchAll();?><div class="panel"><h2>Your QR setup is ready</h2><p class="muted">Print these later from QR Codes. Scan one now to test the customer experience.</p><?php foreach($qr as $r):?><div class="row"><div><b><?=e($r['label'])?></b><div class="small muted"><?=e($r['location_name']??'Guest access')?></div></div><a class="btn" href="qr-card.php?id=<?=$r['id']?>">View QR</a></div><?php endforeach;?><div class="actions"><a class="btn" href="qr.php">Manage all QR codes</a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="finish"><button class="btn gold">Finish setup →</button></form></div></div><?php endif;?>
<?php if($step===7):?><div class="panel onboarding-complete"><div class="complete-icon">✓</div><h2>You’re ready to use SERV.</h2><p class="muted">Your <?=TRIAL_DAYS?>-day trial is active on <b><?=e($plan['plan_name']??'your selected plan')?></b>. You can manage orders, menus, staff and QR codes now.</p><div class="quick-grid"><a class="panel quick" href="index.php"><b>Open dashboard</b><span>See your operation →</span></a><a class="panel quick" href="menu.php"><b>Build your menu</b><span>Add more items →</span></a><a class="panel quick" href="qr.php"><b>Print QR codes</b><span>Guest access →</span></a><a class="panel quick" href="staff.php"><b>Manage staff</b><span>Roles and accounts →</span></a></div></div><?php endif;?>
